parameters.jsCode:
const crypto = require('crypto');

const b = $('Normalize CRM Lead Payload').item.json.body || {};

// تحديد التصنيف الفعلي HOT أو WARM من رد Claude بدل التثبيت على HOT فقط
const modelOutput = $('Claude - Lead Analysis').item.json.choices[0].message.content;
const rawClassification = ((modelOutput.match(/"classification"\s*:\s*"?(HOT|WARM|COLD)/i) || ['', 'COLD'])[1] || 'COLD').toUpperCase();
// Feedback loop rules: only genuinely qualified HOT/WARM leads reach Meta CAPI.
if (!['HOT', 'WARM'].includes(rawClassification)) return [];
const classification = rawClassification;
const leadQuality = classification.toLowerCase();
const qualificationStage = classification === 'HOT' ? 'sales_ready' : 'nurture';
const leadScore = Number((modelOutput.match(/"score"\s*:\s*(\d{1,3})/i) || ['', '0'])[1]);

const rawPhone = String(b.phone || b.contact_phone || '').replace(/[^0-9+]/g, '');
let p = rawPhone.startsWith('+') ? rawPhone.slice(1) : rawPhone;
if (p.startsWith('0020')) { p = p.slice(2); }
else if (p.startsWith('01') && p.length === 11) { p = '20' + p.slice(1); }

const firstName = String(b.contact_name || b.contactName || '').trim().split(' ')[0].toLowerCase();
const contactId = b.contact_id || b.contactId || '';

// === FIX 2: Normalize email ===
const rawEmail = String(b.email || '').trim().toLowerCase();

// === FIX 3a: Capture fbclid and fbp from webhook payload ===
const fbclid = String(b.fbclid || '').trim();
const fbpValue = String(b.fbp || '').trim();

const sha = (v) => crypto.createHash('sha256').update(v).digest('hex');

const eventTime = Math.floor(Date.now() / 1000);
const eventTimeMs = Date.now();

// Build user_data
const user_data = { country: [sha('eg')] };
if (p) { user_data.ph = [sha(p)]; }
if (firstName) { user_data.fn = [sha(firstName)]; }
if (contactId) { user_data.external_id = [sha(String(contactId))]; }

// === FIX 2: Add hashed email ===
if (rawEmail) { user_data.em = [sha(rawEmail)]; }
else { user_data.em = []; }

// === FIX 3b: Build fbc from fbclid (plain text, not hashed) ===
if (fbclid) { user_data.fbc = 'fb.1.' + eventTimeMs + '.' + fbclid; }

// === FIX 3c: Pass fbp (plain text, not hashed) ===
if (fbpValue) { user_data.fbp = fbpValue; }

// === FIX 4: event_id based on contactId for dedup matching ===
const idPrefix = 'lead_' + classification.toLowerCase() + '_';
// Browser and server share this ID to let Meta deduplicate the Lead event.
const browserEventId = String(b.event_id || '').trim();
const eventSourceUrl = String(b.event_source_url || '').trim();
const event_id = browserEventId || (contactId ? (idPrefix + contactId) : (idPrefix + eventTime));

return [{
  json: {
    data: [
      {
        event_name: 'Lead',
        event_time: eventTime,
        event_id: event_id,
        action_source: 'website',   // === FIX 1: was "chat" ===
        event_source_url: eventSourceUrl || undefined,
        user_data: user_data,
        custom_data: {
          content_category: 'qualified_lead',
          content_name: 'Egy Pioneers Webinar Qualified Lead',
          lead_quality: leadQuality,
          qualification_stage: qualificationStage,
          lead_score: Number.isFinite(leadScore) ? Math.min(Math.max(leadScore, 0), 100) : 0
        }
      }
    ]
  }
}];

