parameters.jsCode:
const incoming = $json || {};
const b = incoming.body || {};
const name = String(b.contact_name || b.full_name || b.contactName || b.name || '').replace(/\s+/g, ' ').trim();
const phone = String(b.phone || b.contact_phone || '').replace(/[^0-9+]/g, '').trim();
const email = String(b.email || '').trim().toLowerCase();
const originalContact = b.contact || {};
const originalAttribution = originalContact.attributionSource || originalContact.lastAttributionSource || {};
return [{
  json: {
    ...incoming,
    body: {
      ...b,
      contact_name: name,
      full_name: name,
      contactName: name,
      phone,
      contact_phone: phone,
      email,
      country: b.country || 'EG',
      source: b.source || 'Webinar Landing Page',
      tags: b.tags || 'webinar-landing, Egy-Pioneers-Campaign',
      contact: {
        ...originalContact,
        attributionSource: {
          ...originalAttribution,
          sessionSource: originalAttribution.sessionSource || 'Landing Page',
          medium: originalAttribution.medium || 'website',
          campaign: originalAttribution.campaign || 'EPA Webinar Registration',
          utmContent: originalAttribution.utmContent || 'webinar_landing_form'
        }
      }
    }
  }
}];

const prior = $items('Normalize Landing Lead', 0, 0)[0]?.json || {};
const b = prior.body || {};
const api = $json || {};
const contact = api.contact || {};
const contactId = contact.id || contact.contactId || b.contact_id || b.contactId || '';
const existingContact = b.contact || {};
return [{
  json: {
    ...prior,
    body: {
      ...b,
      contact_id: contactId,
      contactId,
      crm_delivery_status: contactId ? 'CRM created_or_updated' : 'CRM upsert_failed',
      contact: {
        ...existingContact,
        id: contactId,
        attributionSource: existingContact.attributionSource || {
          sessionSource: 'Landing Page',
          medium: 'website',
          campaign: 'EPA Webinar Registration',
          utmContent: 'webinar_landing_form'
        }
      }
    },
    crmContact: contact,
    crmUpsertError: api.error || null
  }
}];

